using System.Diagnostics;using System.Text;using System.Text.Json;using System.Text.RegularExpressions;
namespace TsRecommend;
static class Program {
 static readonly string Home=ConnectionProfiles.Current.Active.Home;
 static readonly string Rock=ConnectionProfiles.Current.Active.Folder;
 static readonly JsonSerializerOptions Json=new(){WriteIndented=true,PropertyNamingPolicy=JsonNamingPolicy.CamelCase};
 static HttpClient Client=null!;static readonly Uri Base=ConnectionProfiles.Current.Active.BaseUri;
 static void Write(string path,object value){Directory.CreateDirectory(Path.GetDirectoryName(path)!);var temp=path+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(value,Json),new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);}
 static string StatusPath=>Path.Combine(Home,"recommend-status.json");
 static void Status(string state,string message,object? detail=null)=>Write(StatusPath,new{state,message,time=DateTimeOffset.Now,detail});
 static async Task<string> Get(string relative){var uri=new Uri(Base,relative);if(!ConnectionProfiles.Current.Active.Allows(uri))throw new Exception("選択した接続先以外への接続を拒否しました。");bool mutation=uri.AbsolutePath.EndsWith("/regsch")||Data.Query(uri.PathAndQuery).ContainsKey("r");for(int attempt=0;;attempt++){try{using var response=await Client.GetAsync(uri);response.EnsureSuccessStatusCode();return Encoding.GetEncoding(932).GetString(await response.Content.ReadAsByteArrayAsync()).TrimEnd('\0');}catch(Exception ex) when(!mutation&&attempt<3&&(ex is HttpRequestException||ex is TaskCanceledException)){await Task.Delay(1500*(attempt+1));}}}
 static List<Booking> Current()=>Data.Bookings(Path.Combine(Rock,"tvrock.sch"));
 static async Task<Booking?> Confirm(Show p,HashSet<string> before){for(int i=0;i<8;i++){var matches=Current().Where(b=>!before.Contains(b.Id)&&b.Enabled&&Planner.SameBroadcast(p,b)&&Data.BookingTitleKey(b.Title)==Data.BookingTitleKey(p.Title)).ToList();if(matches.Count==1)return matches[0];await Task.Delay(500);}return null;}
 static async Task<int> Repair(string run){var attempt=JsonDocument.Parse(File.ReadAllText(Path.Combine(run,"attempt-1.json")));var pick=JsonSerializer.Deserialize<Pick>(attempt.RootElement.GetProperty("pick").GetRawText(),Json)!;var before=Data.Bookings(Path.Combine(run,"tvrock-before.sch")).Select(b=>b.Id).ToHashSet();var current=Current();var candidates=current.Where(b=>!before.Contains(b.Id)&&Planner.SameBroadcast(pick.Show,b)&&Data.Norm(b.Title)==Data.Norm(pick.Show.Title)).ToList();if(candidates.Count!=1)throw new Exception("最初の追加予約を一意に照合できません。");var target=candidates[0];var(tuners,_)=Data.Tuners(Path.Combine(Rock,"dtv.ini"),Data.TunerDevices(await Get("reg")));var device=Planner.FreeDevice(pick.Show,tuners,current.Where(b=>b.Id!=target.Id).ToList(),[]);var form=await Get("reg?i="+target.Id);File.WriteAllText(Path.Combine(run,"repair-before.html"),form);var fields=Data.Form(form,device==null?"予約を削除":"予約を変更");if(fields.GetValueOrDefault("i")!=target.Id||Data.Norm(fields.GetValueOrDefault("title",""))!=Data.Norm(target.Title))throw new Exception("追加予約の編集照合に失敗しました。i="+fields.GetValueOrDefault("i","missing")+" title="+fields.GetValueOrDefault("title","missing"));if(device!=null)fields["devno"]=device.Value.ToString();await Get("regsch?"+string.Join("&",fields.Select(p=>Data.Encode(p.Key)+"="+Data.Encode(p.Value))));await Task.Delay(1000);var updated=Current().SingleOrDefault(b=>b.Id==target.Id);if(device==null){if(updated!=null)throw new Exception("追加予約の取消確認に失敗しました。");Status("repaired","空きがなかったため追加予約を取り消し、既存予約を保護しました。");return 0;}if(updated==null||updated.Device!=device)throw new Exception("チューナー変更を確認できませんでした。");string reason=$"検索条件・予約履歴「{pick.SearchWord}」に関連。既存予約を避け、チューナー{device.Value-4}に割り当てました。";string path=Path.Combine(Home,"ai-recommendations.json");var metadata=File.Exists(path)?JsonSerializer.Deserialize<List<Recommendation>>(File.ReadAllText(path),Json)??[]:[];metadata.RemoveAll(r=>r.ReservationId==updated.Id);metadata.Add(new(updated.Id,updated.Title,pick.SearchWord,reason,updated.Start,updated.Station));Write(path,metadata);Write(Path.Combine(run,"repair-result.json"),new{updated.Id,updated.Device,reason});Status("repaired","追加済み予約のチューナー競合を修正し、おすすめの記録を復元しました。");Console.WriteLine($"Repaired {updated.Id}: tuner {updated.Device-4}");return 0;}
 static async Task<int> Main(string[] args){
  Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);Directory.CreateDirectory(Home);
  if(args.Contains("--quantum-test"))return QuantumCognitionTests.Run();
  if(args.Contains("--audit")){Console.WriteLine(JsonSerializer.Serialize(Current(),Json));return 0;}
  using var mutex=new Mutex(true,"Local\\TsScheduler.Recommendations",out bool own);if(!own)return 0;
  if(args.Contains("--test")){try{Tests.Run();CognitionProtocolTests.Run();return 0;}catch(Exception error){Console.WriteLine(error);return 1;}}
  var now=DateTimeOffset.Now;var state=CognitionHistory.ReadState(Home);bool scheduled=args.Contains("--scheduled"),apply=args.Contains("--apply");
  string? snapshot=args.Contains("--snapshot")?args[Array.IndexOf(args,"--snapshot")+1]:null;
  if(snapshot!=null&&apply)throw new InvalidOperationException("保存済み番組表から実予約はできません。");
  bool Off()=>File.Exists(Path.Combine(Home,"recommend-disabled.txt"));
  if(scheduled&&(Off()||(state.PolicyVersion>=CognitionHistory.Protocol&&state.NextDue>now)))return 0;
  Client=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(12)};Client.DefaultRequestHeaders.ConnectionClose=true;
  if(args.Contains("--repair"))return await Repair(args[Array.IndexOf(args,"--repair")+1]);
  string run=Path.Combine(Home,"recommend-history",now.ToString("yyyyMMdd-HHmmss-fff"));Directory.CreateDirectory(run);var added=new List<string>();var removed=new List<string>();
  void SaveState()=>CognitionHistory.StoreState(Home,state,now);
  try{
   Status("running",apply?"量子コンテキストでおすすめを選定しています。":"予約を変更せず、おすすめ案を作成しています。");
   var bookings=Current();string metadataPath=Path.Combine(Home,"ai-recommendations.json");var known=File.Exists(metadataPath)?JsonSerializer.Deserialize<List<Recommendation>>(File.ReadAllText(metadataPath),CognitionHistory.Json)??throw new InvalidDataException("おすすめ記録を確認してください。"):[];
   var aiIds=known.Where(r=>bookings.Any(b=>CognitionHistory.Matches(r,b))).Select(r=>r.ReservationId).ToHashSet();bookings=bookings.Select(b=>aiIds.Contains(b.Id)?b with{Manual=false}:b).ToList();
   if(!state.LegacyAccountingInitialized){state.LegacyUnconfirmed=Math.Max(0,state.AddedInCycle-known.Count);state.LegacyAccountingInitialized=true;}
   if(state.CycleStarted==null||now-state.CycleStarted>=TimeSpan.FromDays(3)){state.CycleStarted=now;state.AddedInCycle=0;state.LegacyUnconfirmed=0;state.Pending.RemoveAll(p=>p.Time<=now.AddDays(-3));state.Attempted=state.Pending.Select(p=>p.Key).ToList();}
   state.Pending.RemoveAll(p=>known.Any(r=>r.Key==p.Key));
   state.PolicyVersion=CognitionHistory.Protocol;
   var history=CognitionHistory.Reconcile(Home,bookings,known,state,now,apply);
   File.Copy(Path.Combine(Rock,"tvrock.sch"),Path.Combine(run,"tvrock-before.sch"),true);File.Copy(Path.Combine(Rock,"dtv.ini"),Path.Combine(run,"dtv-before.ini"),true);
   var webDevices=snapshot==null?Data.TunerDevices(await Get("reg")):null;if(webDevices is {Count:0})throw new InvalidOperationException("チューナー一覧を取得できません。");var(tuners,stations)=Data.Tuners(Path.Combine(Rock,"dtv.ini"),webDevices);if(tuners.Count==0)throw new InvalidOperationException("使用可能なチューナーがありません。");
   string keywords=snapshot!=null?File.ReadAllText(Path.Combine(snapshot,"keywords.html")):await Get("kwl");File.WriteAllText(Path.Combine(run,"keywords.html"),keywords);
   var learning=new CognitionLearning(history,now);var tastes=Data.Preferences(keywords,bookings.Where(b=>!aiIds.Contains(b.Id)).ToList()).Concat(learning.Tastes()).GroupBy(t=>Data.Norm(t.Text)).Select(g=>g.MaxBy(t=>t.Weight)!).ToList();var consulted=ConsultPreferences.Load(Home);tastes=consulted.AddTo(tastes);if(tastes.Count==0)throw new InvalidOperationException("好みの判断に使える予約・検索条件がありません。");
   var shows=new List<Show>();var day=new DateTimeOffset(now.AddHours(-4).Date,now.Offset);
   for(int offset=0;offset<192;offset+=6){string html=snapshot!=null?File.ReadAllText(Path.Combine(snapshot,$"guide-{offset}.html")):await Get($"day?t={offset}&j=-1&k=-1&v=0");File.WriteAllText(Path.Combine(run,$"guide-{offset}.html"),html);shows.AddRange(Data.Guide(html,offset,day,stations));if(snapshot==null)await Task.Delay(150);}
   shows=shows.Where(s=>!CognitionHistory.CancelledBroadcast(history,s)).GroupBy(s=>s.Key).Select(g=>g.OrderByDescending(s=>s.End).First()).ToList();if(shows.Count<20)throw new InvalidOperationException("番組表を十分取得できませんでした。予約は変更しません。");
   var options=RecommendationOptions.Load(Home);if(options.PreventMarkedRepeats){var blocked=MarkedEpisodes.Load(Home);shows=shows.Where(s=>!MarkedEpisodes.Blocks(blocked,s)).ToList();}
   var qOptions=QuantumCognitionOptions.Load(Home);var quantum=new QuantumCognition(history,now,qOptions);var ranker=new Ranker(tastes);var audit=new Dictionary<string,QuantumRankAudit>();
   (double Score,string Word,string Reason) Score(Show show){var basic=ranker.Score(show);var classical=learning.Evaluate(show);var q=quantum.Evaluate(show,classical.Factor);audit[show.Key]=new(show.Key,show.Title,show.Start,basic.Score,basic.Score*classical.Factor,basic.Score*q.Factor,q);return(basic.Score*q.Factor,basic.Word,basic.Reason+classical.Reason+q.Reason);}
   var plan=Planner.Make(shows.Where(consulted.Allows).ToList(),bookings,tastes,tuners,now,options.Remaining(CognitionHistory.Used(history,state,now)),Score) with{Remove=[]};
   void SaveComparison(){var comparison=new{model=CognitionHistory.Algorithm,adapter="tvrock-v1",enabled=qOptions.Enabled,weight=qOptions.Weight,time=now,candidates=audit.Count,changed=audit.Values.Count(a=>Math.Abs(a.ProductionScore-a.ClassicalScore)>1e-9),selected=added.Count,items=audit.Values.Where(a=>a.Selected).Concat(audit.Values.OrderByDescending(a=>a.ProductionScore).Take(256)).DistinctBy(a=>a.Key)};Write(Path.Combine(Home,"quantum-ranking-latest.json"),comparison);Write(Path.Combine(Home,"quantum-comparisons",now.UtcDateTime.ToString("yyyyMMdd-HHmmss-fffffff")+".json"),comparison);}
   Write(Path.Combine(run,"plan.json"),plan);Write(Path.Combine(Home,"recommend-plan.json"),plan);
   if(!apply){SaveComparison();Status("preview",$"おすすめ候補 {plan.Add.Count}件。予約は未変更です。",new{run,algorithm=CognitionHistory.Algorithm});Console.WriteLine(JsonSerializer.Serialize(plan,Json));return 0;}
   state.NextDue=now.AddMinutes(30);SaveState();
   foreach(var pick in plan.Add){
    if(scheduled&&Off())break;var fresh=Current();history=CognitionHistory.Reconcile(Home,fresh,known,state,DateTimeOffset.Now);
    if(options.Remaining(CognitionHistory.Used(history,state,DateTimeOffset.Now))==0)break;
    if(state.Attempted.Contains(pick.Show.Key)||CognitionHistory.CancelledBroadcast(history,pick.Show)||fresh.Any(b=>b.Enabled&&(Planner.SameBroadcast(pick.Show,b)||Planner.SameEpisode(pick.Show.Title,pick.Show.Description,b.Title,b.Fields.GetValueOrDefault("SUBTITLE","")))))continue;
    var device=Planner.FreeDevice(pick.Show,tuners,fresh,[]);if(device==null)continue;var query=Data.Query(pick.Show.Actions[device.Value]);if(query.GetValueOrDefault("r")!="1"||query.GetValueOrDefault("c")!=pick.Show.ServiceId.ToString()||query.GetValueOrDefault("e")!=pick.Show.EventId.ToString()||query.GetValueOrDefault("d")!=device.Value.ToString())throw new InvalidOperationException("番組表の予約リンクが一致しません。");
    state.Attempted.Add(pick.Show.Key);state.Pending.Add(new(pick.Show.Key,DateTimeOffset.Now));state.AddedInCycle++;SaveState();Write(Path.Combine(run,"attempt-"+state.AddedInCycle+".json"),new{pick,beforeIds=fresh.Select(b=>b.Id)});
    await Get(pick.Show.Actions[device.Value]);var created=await Confirm(pick.Show,fresh.Select(b=>b.Id).ToHashSet());if(created==null)throw new IOException("追加結果を確認できません。二重登録防止のため自動再送は停止しました。");
    known.Add(new(created.Id,created.Title,pick.SearchWord,pick.Reason,created.Start,created.Station,consulted.Include.Length>0?"gpt-preferences":"local",DateTimeOffset.Now,created.End,pick.Show.Key));Write(metadataPath,known);state.Pending.RemoveAll(p=>p.Key==pick.Show.Key);SaveState();audit[pick.Show.Key].Selected=true;added.Add(created.Id);Write(Path.Combine(run,"result.json"),new{added,removed});
   }
   // As in Studio, ranking must not silently remove existing reservations.
   SaveComparison();state.NextDue=DateTimeOffset.Now.AddMinutes(30);SaveState();
   Status("complete",$"おすすめ {added.Count}件を追加しました（直近3日の有効件数で上限、取消分は枠へ返却、量子コンテキスト "+(qOptions.Enabled?"ON":"OFF")+"）。",new{added,removed,nextDue=state.NextDue,algorithm=CognitionHistory.Algorithm,adapter="tvrock-v1",run});return 0;
  }catch(Exception error){state.NextDue=DateTimeOffset.Now.AddMinutes(30);try{SaveState();}catch{}Status(added.Count>0?"partial":"failed",(added.Count>0?$"{added.Count}件は予約済みです。その後は停止しました。":"")+error.Message,new{run});File.WriteAllText(Path.Combine(run,"error.txt"),error.ToString());Console.Error.WriteLine(error);return 1;}
  finally{Client.Dispose();}
 }
}
record Suppression(string ReservationId,string ProgramTitle,string KeepId,string Reason);
static class Tests {
 static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
 public static void Run(){string fixture=Path.GetTempFileName();File.WriteAllText(fixture,"0 START 2000000000\n0 END 2000000600\n0 UNIQID 10\n0 VALIDATE 1\n1 START 2000000700\n1 END 2000001300\n1 UNIQID 11\n1 VALIDATE 1\n",Data.Cp932);Assert(Data.Bookings(fixture).Count==2,"複数の予約連番を読み取れない");var now=DateTimeOffset.Now;Show S(int index,DateTimeOffset? start=null)=>new($"show-{index}",1,index,"NHK",$"工場見学「部品{index}の秘密」","金属部品を製造する職人の工夫を紹介します。",start??now.AddHours(2+index), (start??now.AddHours(2+index)).AddMinutes(30),new(){{5,"day?r=1&c=1&e="+index+"&d=5"}});Booking B(string id,DateTimeOffset start,int device=5)=>new(id,"既存予約","NHK",1,99,start,start.AddHours(1),device,true,true,false,[]);var tuners=new List<Tuner>{new(5,["NHK"])};Assert(Planner.FreeDevice(S(1,now.AddHours(2)),tuners,[B("a",now.AddHours(2))],[])==null,"競合を検出できない");Assert(Planner.FreeDevice(S(1,now.AddHours(4)),tuners,[B("a",now.AddHours(2))],[])==5,"空き枠を選べない");Assert(!Planner.SameEpisode("NHKスペシャル","番組説明","NHKスペシャル","番組説明"),"同名別回を誤判定");Assert(Planner.SameEpisode("工場見学「部品の秘密」[再]","","工場見学「部品の秘密」[字]",""),"再放送の同回を認識できない");Assert(!Planner.SameEpisode("工場見学「部品の秘密」","","工場見学「金属の秘密」",""),"別回を誤判定");var guide=Enumerable.Range(1,40).Select(i=>S(i)).ToList();var capTastes=guide.Select(p=>new Taste(p.Title,1)).ToList();var plan=Planner.Make(guide,[],capTastes,tuners,now);Assert(plan.Add.Count==20,"20件上限・選定失敗");var form=Data.Form("<form name='regsch'><input name='i' value='12' type='hidden'><input type='checkbox' name='valid' value='true' checked><input type='checkbox' name='watchonly' value='true'><input type='submit' name='submit' value='　予約を削除　'></form>","予約を削除");Assert(form["i"]=="12"&&form.ContainsKey("valid")&&!form.ContainsKey("watchonly")&&form["submit"].Contains("削除"),"フォーム保持失敗");Assert(Data.Encode("NHK 日本").Contains("%93%FA%96%7B"),"CP932符号化失敗");var r=new Ranker([new("MUSIC not (BRAND|BLOOD)",1),new("NHKスペシャル",1),new("サカナクション",1)]);Assert(r.Score(S(100) with{Title="BRAND NEW MUSIC"}).Score==0,"検索除外語を無視した");Assert(r.Score(S(101) with{Title="NHKスペシャルPR [字]"}).Score==0,"PR番組を除外できない");Assert(r.Score(S(102) with{Title="ハクション大魔王"}).Score==0,"無関係な語尾一致を推薦した");Assert(!Planner.SameEpisode("ニュース","毎日の全国のニュースや天気の情報を詳しくお届けします。","ニュース","毎日の全国のニュースや天気の情報を詳しくお届けします。"),"一般的な説明の一致だけで別回を消した");Assert(!Planner.SameEpisode("【ハートネットTV】","","【ハートネットTV】",""),"番組枠名だけで別回を消した");Assert(Planner.Make(guide,[],capTastes,tuners,now,3).Add.Count==3,"周期の残件数を超えた");Console.WriteLine("PASS: tuner conflict, free slot, same-episode vs generic title, 20-cap, form checkboxes, CP932 encoding.");}
}
